DROP POLICY IF EXISTS "follows readable by everyone" ON public.follows;
CREATE POLICY "follows readable by signed-in" ON public.follows FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "adverts readable" ON public.adverts;
CREATE POLICY "adverts readable by signed-in" ON public.adverts FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "likes readable by everyone" ON public.likes;
CREATE POLICY "likes readable by signed-in" ON public.likes FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Signed-in users view reposts" ON public.reposts;
CREATE POLICY "Signed-in users view reposts" ON public.reposts FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Marketplace signed-in read" ON public.marketplace_listings;
CREATE POLICY "Marketplace signed-in read" ON public.marketplace_listings FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "posts readable by everyone" ON public.posts;
CREATE POLICY "posts readable by signed-in" ON public.posts FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Gallery is viewable by everyone" ON public.gallery_items;
CREATE POLICY "Gallery viewable by signed-in" ON public.gallery_items FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Anyone signed in can read the family tree" ON public.family_members;
CREATE POLICY "Anyone signed in can read the family tree" ON public.family_members FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "profiles readable by everyone" ON public.profiles;
CREATE POLICY "profiles readable by signed-in" ON public.profiles FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "groups readable" ON public.groups;
CREATE POLICY "groups readable by signed-in" ON public.groups FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "comments readable by everyone" ON public.comments;
CREATE POLICY "comments readable by signed-in" ON public.comments FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Module settings are readable by everyone" ON public.module_settings;
CREATE POLICY "Module settings readable by signed-in" ON public.module_settings FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
CREATE POLICY "Visitors see hidden module flags" ON public.module_settings FOR SELECT TO anon USING (visible = false);
DROP POLICY IF EXISTS "Directory signed-in read" ON public.directory_entries;
CREATE POLICY "Directory signed-in read" ON public.directory_entries FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "gm readable by signed-in" ON public.group_members;
CREATE POLICY "gm readable by signed-in" ON public.group_members FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "convo insert auth" ON public.conversations;
CREATE POLICY "convo insert auth" ON public.conversations FOR INSERT TO authenticated WITH CHECK (created_by = auth.uid());
DROP POLICY IF EXISTS "post-images public read" ON storage.objects;
CREATE POLICY "post-images signed-in read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'post-images' AND auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "avatars public read" ON storage.objects;
CREATE POLICY "avatars signed-in read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'avatars' AND auth.uid() IS NOT NULL);